import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'

import { FEATURE_FLAGS } from 'lib/constants'
import { FeatureFlagsSet, featureFlagLogic } from 'lib/logic/featureFlagLogic'

import { sidePanelStateLogic } from '~/layout/navigation-3000/sidepanel/sidePanelStateLogic'
import { SidePanelTab } from '~/types'

import { PHAI_SCENE_AUTO_OPEN_DISMISSED_KEY } from './max-storage-keys'
import { PhaiViewMode, maxGlobalLogic } from './maxGlobalLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sceneAgentPanelLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    effectivePhaiView: PhaiViewMode // maxGlobalLogic
    isMaxAvailable: boolean // maxGlobalLogic
    modalMode: boolean // sidePanelStateLogic
    selectedTab: SidePanelTab | null // sidePanelStateLogic
    sidePanelAvailable: boolean // sidePanelStateLogic
    sidePanelOpen: boolean // sidePanelStateLogic
    activeSceneKeys: string[]
    autoOpenDismissedScenes: Record<string, true>
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sceneAgentPanelLogicActions {
    openSidePanel: (
        tab: SidePanelTab,
        options?: string | undefined
    ) => {
        options: string | undefined
        tab: SidePanelTab
    } // sidePanelStateLogic
    markAutoOpenDismissed: (sceneKeys: string[]) => {
        sceneKeys: string[]
    }
    sceneEntered: (sceneKey: string) => {
        sceneKey: string
    }
    sceneLeft: (sceneKey: string) => {
        sceneKey: string
    }
}

export type sceneAgentPanelLogicType = MakeLogicType<sceneAgentPanelLogicValues, sceneAgentPanelLogicActions>

/**
 * Auto-opens the PostHog AI side panel for scenes that opt in (via `useSceneAgentPanel`), with a
 * persisted per-scene opt-out: once the user closes the panel while such a scene is active, that
 * scene stops auto-opening on this device. Only ever opens the new (sandbox) view — the legacy Max
 * view has its own scene-context system and predates this behavior.
 */
export const sceneAgentPanelLogic = kea<sceneAgentPanelLogicType>([
    path(['scenes', 'max', 'sceneAgentPanelLogic']),
    connect(() => ({
        values: [
            featureFlagLogic,
            ['featureFlags'],
            maxGlobalLogic,
            ['effectivePhaiView', 'isMaxAvailable'],
            sidePanelStateLogic,
            ['sidePanelOpen', 'selectedTab', 'sidePanelAvailable', 'modalMode'],
        ],
        actions: [sidePanelStateLogic, ['openSidePanel']],
    })),
    actions({
        sceneEntered: (sceneKey: string) => ({ sceneKey }),
        sceneLeft: (sceneKey: string) => ({ sceneKey }),
        markAutoOpenDismissed: (sceneKeys: string[]) => ({ sceneKeys }),
    }),
    reducers({
        activeSceneKeys: [
            [] as string[],
            {
                sceneEntered: (state, { sceneKey }) => (state.includes(sceneKey) ? state : [...state, sceneKey]),
                sceneLeft: (state, { sceneKey }) => state.filter((key) => key !== sceneKey),
            },
        ],
        autoOpenDismissedScenes: [
            {} as Record<string, true>,
            { persist: true, storageKey: PHAI_SCENE_AUTO_OPEN_DISMISSED_KEY },
            {
                markAutoOpenDismissed: (state, { sceneKeys }) => ({
                    ...state,
                    ...Object.fromEntries(sceneKeys.map((key) => [key, true as const])),
                }),
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        sceneEntered: ({ sceneKey }) => {
            if (
                !values.featureFlags[FEATURE_FLAGS.PHAI_SCENE_AUTO_OPEN] ||
                values.effectivePhaiView !== 'new' ||
                !values.isMaxAvailable ||
                !values.sidePanelAvailable ||
                // In modal mode (narrow viewports) the panel overlays the whole scene — never force it open.
                values.modalMode ||
                values.autoOpenDismissedScenes[sceneKey] ||
                // Already open: either on Max (nothing to do) or on a tab the user chose (don't clobber it).
                values.sidePanelOpen
            ) {
                return
            }
            actions.openSidePanel(SidePanelTab.Max)
        },
        [sidePanelStateLogic.actionTypes.closeSidePanel]: ({ tab }: { tab?: SidePanelTab }) => {
            // Any close of the Max tab while an opted-in scene is active counts as "stop auto-opening
            // here" — regardless of whether this logic or the user opened the panel.
            if (values.activeSceneKeys.length === 0) {
                return
            }
            if ((tab && tab !== SidePanelTab.Max) || values.selectedTab !== SidePanelTab.Max) {
                return
            }
            actions.markAutoOpenDismissed(values.activeSceneKeys)
        },
    })),
])
